static const lv_image_dsc_t icon_eth = {
  .header = {.magic = LV_IMAGE_HEADER_MAGIC, .cf = LV_COLOR_FORMAT_RGB565A8,
             .flags = 0, .w = 24, .h = 24, .stride = 48},
  .data_size = sizeof(icon_eth_data),
  .data = icon_eth_data,
};

static const struct {
  const char* symbol;
  const lv_image_dsc_t* icon;
} kIcons[] = {
    {"SOL", &icon_sol},
    {"USDC", &icon_usdc},
    {"USDT", &icon_usdt},
    {"JUP", &icon_jup},
    {"BONK", &icon_bonk},
    {"PYTH", &icon_pyth},
    {"JitoSOL", &icon_jitosol},
    {"mSOL", &icon_msol},
    {"bSOL", &icon_bsol},
    {"WIF", &icon_wif},
    {"RAY", &icon_ray},
    {"JTO", &icon_jto},
    {"BTC", &icon_btc},
    {"ETH", &icon_eth},
};

const lv_image_dsc_t* tokenIcon(const char* symbol) {
  for (size_t i = 0; i < sizeof kIcons / sizeof kIcons[0]; i++) {
    if (strcmp(kIcons[i].symbol, symbol) == 0) return kIcons[i].icon;
  }
  return NULL;
}
